export function Element({
  highlight = "{{highlight}}",
  accent = "{{accent}}",
  showTags = {{showTags}},
}) {
  const box = (key) => ({ border: `2px dashed ${highlight === key ? accent : "transparent"}`, background: highlight === key ? "#24143008" : "transparent", borderRadius: 6, padding: 8 });
  const tag = (name) => showTags && <code style={{ fontSize: 10, opacity: .6, display: "block", marginBottom: 3 }}>&lt;{name}&gt;</code>;
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ ...box("div"), display: "block" }}>
        {tag("div")}
        <span style={{ ...box("span"), display: "inline-block", margin: "6px 4px 0" }}>{tag("span")} Text</span>
        <button type="button" style={{ ...box("button"), display: "inline-block", margin: "6px 4px 0" }}>{tag("button")} Go</button>
      </div>
      <p style={{ margin: "10px 0 0" }}>Every tag in the tree is an element &mdash; the outlined one is highlighted</p>
    </div>
  );
}
